#!/usr/bin/env bash
# generated by team.sh — starts the 'designer' agent
export ATOMIC_ROLE=designer
export ATOMIC_INTERCOM_GROUP=cockpit
export BUILD_DIR=/Users/mp/git-repos/atomic-cockpit/build
export TEAMCHAT_FEED=/Users/mp/git-repos/atomic-cockpit/build/team-chat.log
cd "/Users/mp/git-repos/atomic-cockpit"
atomic -e /Users/mp/git-repos/atomic-cockpit/atomic/extensions/herdr-state.ts -e /Users/mp/git-repos/atomic-cockpit/atomic/extensions/intercom-bridge.ts --provider anthropic --model claude-sonnet-5 -n designer \
  --append-system-prompt "$(cat /Users/mp/git-repos/atomic-cockpit/team/designer.md)" \
  --append-system-prompt "$(cat /Users/mp/git-repos/atomic-cockpit/team/TRANSPORT.md)" \
  2> >(tee -a /Users/mp/git-repos/atomic-cockpit/build/.launch/designer.stderr.log >&2)
status=$?
echo; echo "[cockpit] the 'designer' session exited (status $status). Pane kept open."
echo "[cockpit] stderr: /Users/mp/git-repos/atomic-cockpit/build/.launch/designer.stderr.log"
echo "[cockpit] restart with: bash /Users/mp/git-repos/atomic-cockpit/build/.launch/designer.sh"
